function bar(container, label, value, maxAbs, color) {
  const row = document.createElement('div');
  row.className = 'bar-row';
  const pct = Math.min(Math.abs(value) / maxAbs * 50, 50);
  const isNeg = value < 0;
  row.innerHTML = `
    <div class="bar-label">${label}</div>
    <div class="bar-track">
      <div class="bar-zero"></div>
      <div class="bar-fill" style="position:absolute; ${isNeg ? 'right:50%;' : 'left:50%;'} width:${pct}%; background:${color};"></div>
    </div>
    <div class="bar-value" style="color:${isNeg?'#d03b3b':'#0b0b0b'}">${value>0?'+':''}${value.toFixed(1)}%</div>
  `;
  container.appendChild(row);
}
const el = document.getElementById('bar-chart');
const maxAbs = 14;
bar(el, '시장 요구 성장률 (WACC 10%)', 5.6, maxAbs, '#2a78d6');
bar(el, '위기 이전 실제 FCF 성장률 (21→23)', 13.6, maxAbs, '#1baf7a');
bar(el, '최근 5년 실제 FCF 성장률 (21→25)', -5.2, maxAbs, '#d03b3b');
bar(el, '최근 5년 실제 매출 성장률 (21→25)', 11.7, maxAbs, '#eda100');
